      drawPanel(state.landed || state.status === 'won' ? 'Misi Selesai!' : 'Penerbangan Berakhir', lines, 'Tekan Spasi untuk terbang lagi');
    }
  }

  resize();
  window.addEventListener('resize', resize);
  return { draw };
}
